def prepare_case(source: Path) -> dict[str, Any]:
    files, warnings = load_files(source)
    meta = {**json.loads(files.get("result.json", "{}")), **json.loads(files.get("case.json", "{}"))}
    question = meta.get("question", "")
    report = files.get("report.md") or meta.get("final_response", "")
    injections: dict[tuple[str, str], list[dict]] = {}
    for name, text in files.items():
        if name.endswith("requests.jsonl"):
            for line, row in rows(text, name, warnings):
                if row.get("call") is not None:
                    key = (owner(name), str(row["call"]))
                    injections.setdefault(key, []).append({**row, "source_path": name, "line": line})
    steps = []
    for name, text in sorted(files.items()):
        if not name.endswith(".jsonl") or "trajectories" not in name.split("/"):
            continue
        records = rows(text, name, warnings)
        digest = sha(text)
        starts = [r for _, r in records if r.get("t") == "start"]
        question = question or (starts[0].get("user_message", "") if starts else "")
        previous = []
        for index, (line, row) in enumerate(records):
            if row.get("t") != "llm":
                continue
            call = row.get("turn")
            matches = injections.get((owner(name), str(call)), [])
            unique = {json.dumps({k: m.get(k) for k in ("system_memory", "graph_chars", "fallback")}, sort_keys=True)
                      for m in matches}
            match = matches[0] if len(unique) == 1 else None
            graph_text, status = "", "missing" if not matches else "ambiguous"
            if match:
                blocks = re.findall(r"<belief_graph>([\s\S]*?)</belief_graph>", match.get("system_memory", ""))
                if match.get("fallback"):
                    status = "fallback"
                elif len(blocks) == 1:
                    graph_text = blocks[0].strip()
                    status = "matched" if graph_text else "empty"
                elif match.get("graph_chars") == 0:
                    status = "empty"
            thinking = content(row.get("reasoning_content") or row.get("thinking") or row.get("reasoning"))
            action = "\n\n".join(x for x in (
                "Thinking:\n" + thinking if thinking else "", content(row.get("content")),
                "Tool calls:\n" + json.dumps(row["tool_calls"], ensure_ascii=False, indent=2) if row.get("tool_calls") else "",
            ) if x)
            results = []
            for _, following in records[index + 1:]:
                if following.get("t") == "llm":
                    break
                if following.get("t") == "result" and str(following.get("turn")) == str(call):
                    results.append({"tool": following.get("name"), "tool_call_id": following.get("tool_call_id"),
                                    "text": content(following.get("result"))})
            step = {
                "id": "S" + sha(f"{name}:{digest}:{line}")[:16], "call": call, "agent": owner(name) or "Agent",
                "source": {"path": name, "digest": digest, "index": line, "call": call},
                "graph": {**clipped(graph_text, 30000), "status": status,
                          "source_path": match.get("source_path") if match else None,
                          "source_line": match.get("line") if match else None},
                "action_text": clipped(action, 16000),
                "tool_results": clipped(json.dumps(results, ensure_ascii=False, indent=2), 18000),
                "previous_calls": [{"id": p["id"], "call": p["call"],
                    "action_text": clipped(p["action_text"]["text"], 3000),
                    "tool_results": clipped(p["tool_results"]["text"], 3000)} for p in previous[-2:]],
                "retained_indices": match.get("retained_indices") if match else None,
            }
            previous.append(step)
            steps.append(step)
    if not steps:
        raise ValueError("No native ReAct llm trajectory records found")
    if not report.strip():
        raise ValueError("No non-empty final report found")
    if not question.strip():
        raise ValueError("Task question is missing")
    identity = sorted((name, sha(text)) for name, text in files.items()
                      if name in {"case.json", "report.md", "result.json"} or name.endswith(".jsonl"))
    return {"format": "bcg-ai-review-evidence", "version": 1,
            "evidence_sha256": sha(json.dumps(identity)),
            "task_id": str(meta.get("task_id") or source.name), "benchmark": meta.get("benchmark", ""),
            "question": clipped(question, 20000), "final_report": clipped(report, 50000),
            "task_status": meta.get("status", "unknown"), "steps": steps,
            "coverage": {"agent_calls": len(steps), "graph_matched_calls": sum(s["graph"]["status"] == "matched" for s in steps),
                         "truncated_calls": sum(any(s[k]["truncated"] for k in ("graph", "action_text", "tool_results")) for s in steps),
                         "warnings": warnings}}

