def batches(case: dict, *, chunk_chars: int = 60000, chunk_turns: int = 6) -> list[dict]:
    groups: list[list[dict]] = []
    group: list[dict] = []
    size = 0
    for step in case["steps"]:
        n = len(json.dumps(step, ensure_ascii=False))
        if group and (size + n > chunk_chars or len(group) >= chunk_turns):
            groups.append(group)
            group, size = [], 0
        group.append(step)
        size += n
    if group:
        groups.append(group)
    return [{"task_id": case["task_id"], "question": case["question"], "final_report": case["final_report"],
             "eligible_ids": [s["id"] for s in g], "steps": g, "coverage": case["coverage"]} for g in groups]

